import re,os
def path(m): return m.replace('.','/')+'.lean'
def imports(f):
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(f).read(),flags=re.M) if os.path.exists(f) else []
# BFS with parents
from collections import deque
par={'AlgebraicJacobian':None}
q=deque(['AlgebraicJacobian'])
target='AlgebraicJacobian.RiemannRoch.Ledger.OrdCompare'
while q:
    m=q.popleft()
    for i in imports(path(m)):
        if i not in par:
            par[i]=m; q.append(i)
c=target; chain=[]
while c: chain.append(c); c=par.get(c)
print(' <- '.join(x.replace('AlgebraicJacobian.','') for x in chain))
